        "final_str": hero_base.get("str", 20) + peak_bonus["str"],
        "final_agi": hero_base.get("agi", 20) + peak_bonus["agi"],
        "final_sta": hero_base.get("sta", 20) + peak_bonus["sta"],
        "final_mag": hero_base.get("mag", 20) + peak_bonus["mag"],
